/*CURSO_MAIS_FIM*/
// cada lição vira um tema de cartões só com as palavras que ainda não existem em outros temas
// shortcut: o id do cartão depende da posição no tema; se um tema antigo ganhar a mesma palavra, o progresso dessa lição se desloca. Fixar ids se o curso crescer.
(() => { const ja = new Set(DECKS.flatMap(d => d.cards.map(c => normCursoPl(c[0]))));
  CURSO.forEach(l => { if (!l.deck) l.deck = "L"+l.id.replace(/[^a-z0-9]/gi, "");
    DECKS.push({id: l.deck, grupo: "curso", nome: `Curso ${l.nivel} · ${l.pt}`, cards: l.pal.filter(p => { const k = normCursoPl(p[0]); if (ja.has(k)) return false; ja.add(k); return true; })}); }); })();
// áudio das lições novas fica em arquivos separados (audio/<id>.json), carregados só quando a frase toca
const AUDIO_IDX = Object.fromEntries(Object.entries(AUDIO_BASE).map(([t, n]) => [t, "base-" + String(n).padStart(2, "0")]));
CURSO.forEach(l => { if (l.audioExt) [...l.pal.map(p => p[0]), ...(l.dial || []).map(d => d[0]), ...(l.texto ? [l.texto] : [])].forEach(t => { if (!AUDIO_IDX[t]) AUDIO_IDX[t] = l.id; }); });
const idxAudio = t => AUDIO_IDX[t] || AUDIO_IDX[t.trim()];

